　あり、正当な理由なく怠ると10万円以下の過料の対象となる★
・相続人申告登記の申出をすれば、相続登記の申請義務を履行した
　ものとみなされる★
・登記名義人の氏名・名称または住所の変更登記も、変更があった日
　から2年以内の申請が義務化され、過料は5万円以下である★
・所有不動産記録証明制度により、特定の者が名義人となっている
　不動産の一覧を証明書として取得できる★

