・従物については、設定当時に存在した従物に効力が及ぶとするのが
　判例である★
・借地上の建物に抵当権が設定された場合、その効力は従たる権利で
　ある敷地の賃借権にも及ぶ★
　→競落人は借地権も取得するが、賃貸人の承諾または裁判所の許可
