　通知の日から6か月を経過することで転貸借は終了する★
・居住用建物の賃借人が相続人なしに死亡した場合、事実上夫婦または
　養親子と同様の関係にあった同居者は、賃借人の権利義務を承継する★
　→承継を望まないときは1か月以内に反対の意思を表示する★

━━━━━━━━━━━━━━━━━━━━━━
