・敷地利用権とは、専有部分を所有するための建物の敷地に関する
　権利をいい、所有権・地上権・賃借権・使用借権がこれに当たる★
・区分所有者は、その有する専有部分とその専有部分に係る敷地利用権
　とを分離して処分することができない★
