【図解】共同申請と単独申請
　場面｜申請人｜補足
　原則｜登記権利者と登記義務者の共同申請★｜真正担保
　所有権保存登記｜表題部所有者等の単独申請★｜甲区に最初にされる登記
　相続・法人の合併による移転｜単独申請★｜登記義務者がいない
　判決による登記｜単独申請★｜確定判決が必要
　登記名義人の氏名等の変更｜単独申請★｜不利益がない

・登記の申請は、当事者の申請または官庁もしくは公署の嘱託がなければ
　することができない（申請主義）★
・共同申請の場合、登記義務者の登記識別情報を提供する必要がある★
